import { test, expect } from '@playwright/test';

test.describe('Remember Me Authentication Feature', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should remember user credentials when "Remember Me" is checked and persist login across sessions', async ({ page }) => {
    // Verify login page is visible
    const loginForm = page.getByRole('form');
    await expect(loginForm).toBeVisible();

    // Verify "Remember Me" checkbox is visible and disabled by default
    const rememberMeCheckbox = page.getByLabel('Remember Me');
    await expect(rememberMeCheckbox).toBeVisible();
    await expect(rememberMeCheckbox).toBeDisabled();

    // Verify login button is visible
    const loginButton = page.getByRole('button', { name: /sign in/i });
    await expect(loginButton).toBeVisible();

    // Verify login form has email and password fields
    const emailInput = page.getByLabel('Email address');
    const passwordInput = page.getByLabel('Password');
    await expect(emailInput).toBeVisible();
    await expect(passwordInput).toBeVisible();

    // Verify login form has error messages
    const errorMessage = page.getByText('Please enter a valid email and password');
    await expect(errorMessage).toBeVisible();

    // Fill in valid credentials
    await emailInput.fill('user@example.com');
    await passwordInput.fill('SecurePassword123');

    // Click login button
    await loginButton.click();

    // Verify login success message appears
    const successMessage = page.getByText('Logged in successfully');
    await expect(successMessage).toBeVisible();

    // Verify user is redirected to home page
    const homePage = page.getByText('Home');
    await expect(homePage).toBeVisible();

    // Verify "Remember Me" checkbox is now enabled
    await expect(rememberMeCheckbox).toBeEnabled();

    // Verify user is logged in across sessions
    await page.reload();
    await expect(homePage).toBeVisible();

    // Verify "Remember Me" checkbox is still enabled
    await expect(rememberMeCheckbox).toBeEnabled();

    // Verify user is logged in after browser restart
    await page.reload();
    await expect(homePage).toBeVisible();

    // Verify "Remember Me" checkbox is still enabled
    await expect(rememberMeCheckbox).toBeEnabled();
  });

